"""Draft server-linked monthly scorecards; no response identity is inferred from labels."""
from datetime import datetime, timezone, timedelta
from zoneinfo import ZoneInfo


def run_scorecards(api):
    settings = api.extension.settings()
    if settings.get("scorecard_enabled") is not True:
        raise ValueError("Scorecard production is disabled in reviewed Hammerjack setup")
    now = datetime.now(ZoneInfo(str(settings.get("timezone", "Asia/Manila"))))
    month = now.strftime("%Y-%m")
    expected_cutoff = (now.date() - timedelta(days=1)).isoformat()
    stamp = datetime.now(timezone.utc).isoformat()

    def records(slug, portal_id):
        rows, cursor = [], None
        for _ in range(10):
            args = {"type_slug": slug, "portal_id": portal_id, "limit": 200}
            if cursor is not None:
                args["cursor"] = cursor
            page = api.records.list(**args)
            if not isinstance(page, dict) or not isinstance(page.get("records"), list):
                raise ValueError("Unknown Records page for " + slug)
            rows.extend(page["records"])
            next_cursor = page.get("nextCursor")
            if next_cursor is None:
                return rows
            if not isinstance(next_cursor, str) or next_cursor == cursor:
                raise ValueError("Invalid Records cursor")
            cursor = next_cursor
        raise ValueError("Scorecard source exceeds the reviewed 2000-row bound")

    response_cache = {}
    def responses(form_id):
        if form_id in response_cache:
            return response_cache[form_id]
        rows, cursor = [], None
        for _ in range(10):
            args = {"form_id": form_id, "limit": 200}
            if cursor is not None:
                args["cursor"] = cursor
            page = api.forms.list_responses(**args)
            if not isinstance(page, dict) or not isinstance(page.get("items"), list):
                raise ValueError("Scorecards need the reviewed paginated Forms response contract")
            rows.extend(page["items"])
            next_cursor = page.get("nextCursor")
            if next_cursor is None:
                response_cache[form_id] = rows
                return rows
            if not isinstance(next_cursor, str) or next_cursor == cursor:
                raise ValueError("Invalid Forms response cursor")
            cursor = next_cursor
        raise ValueError("Review responses exceed the reviewed 2000-response bound; no partial score is written")

    portals = api.portals.list()
    if not isinstance(portals, list) or len(portals) > 100:
        raise ValueError("Portal inventory exceeds the reviewed 100-portal bound")
    planned = []
    for portal in portals:
        portal_id = portal["portalId"]
        attendance = {str(row["data"]["sprout_system_id"]): row for row in records("hj_attendance_month", portal_id) if row["data"].get("month") == month}
        review_rows = [row for row in records("hj_scorecards", portal_id) if row["data"].get("month") == month]
        for current in review_rows:
            data = current["data"]
            system_id = data["sprout_system_id"]
            monthly = attendance.get(str(system_id))
            if not monthly:
                raise ValueError("A reviewed monthly attendance record is required before scorecard projection")
            if monthly["data"].get("calculation_end_date") != expected_cutoff:
                raise ValueError("Attendance calculation must cover every completed local day through yesterday before scorecards run")
            try:
                source_stamp = datetime.fromisoformat(str(monthly["data"].get("synced_at", "")).replace("Z", "+00:00"))
            except ValueError as error:
                raise ValueError("Attendance record has no valid source sync timestamp") from error
            if source_stamp.tzinfo is None:
                raise ValueError("Attendance source sync timestamp must include its timezone")
            age_seconds = (now - source_stamp).total_seconds()
            if not 0 <= age_seconds <= 86400:
                raise ValueError("Attendance source is stale or future-dated; run the reviewed Sprout sync before scorecards")
            rate = monthly["data"].get("attendance_rate")
            if isinstance(rate, bool) or not isinstance(rate, (int, float)) or not 0 <= rate <= 100:
                raise ValueError("Attendance rate must be a verified percentage")
            relevant = []
            if data.get("review_form_id"):
                for response in responses(data["review_form_id"]):
                    if not all(key in response for key in ("portalId", "todoId", "subjectRef", "subjectKind", "submittedAt", "responses")):
                        raise ValueError("Forms automation reader is missing trusted employee linkage; do not infer it from names")
                    if response["portalId"] != portal_id or not response["submittedAt"]:
                        continue
                    linked_item = response["todoId"] == data.get("review_item_id") and response["todoId"] is not None
                    if linked_item:
                        relevant.append(response)
            ratings = []
            for response in relevant:
                answer = response["responses"]
                for key in ("q_overall", "q_quality", "q_comms"):
                    value = answer.get(key)
                    if isinstance(value, bool) or not isinstance(value, (int, float)) or not 1 <= value <= 5:
                        raise ValueError("Submitted review is missing a valid 1–5 rating: " + key)
                    ratings.append(value)
            attendance_component = rate / 100.0 * 5.0
            review_component = sum(ratings) / len(ratings) if ratings else None
            score = 0.10 * attendance_component + 0.90 * review_component if review_component is not None else None
            payload = dict(data, employee_name=current["title"], score=score, attendance_component=attendance_component,
                           review_component=review_component, review_count=len(relevant), synced_at=stamp)
            planned.append({"portal_id": portal_id, "system_id": system_id, "key": data["sync_key"], "title": current["title"], "data": payload})
    # Validate all source pages and ratings before publishing any score. A source
    # problem on a later employee cannot publish an earlier partial calculation.
    for item in planned:
        stored = api.records.upsert(type_slug="hj_scorecards", portal_id=item["portal_id"],
                                    key={"field": "sync_key", "value": item["key"]}, record={"title": item["title"], "data": item["data"]})
        canonical = stored["data"]
        api.snapshots.upsert(portal_id=item["portal_id"], source="sprout", entity_type="scorecard", replace=False,
                             rows=[{"external_id": str(item["system_id"]) + ":" + month, "observed_at": stamp,
                                    "payload": {"employee_name": stored["title"], "month": month, "score": canonical.get("score"),
                                                "attendance_component": canonical["attendance_component"],
                                                "review_component": canonical.get("review_component"), "review_count": canonical["review_count"]}}])
    return {"month": month, "scorecards": len(planned)}


result = run_scorecards(api)
